// glossary.go — определения для панели «Глоссарий» и текст «Методики».
// Один источник правды по семантике отчёта; фиксированные определения
// («представлен», «недоступен», мера остатка 1С) обязаны совпадать с
// формулировкой заказчика отчёта.
package main

type glossaryEntry struct{ Term, Def string }
type glossarySection struct {
	Title   string
	Entries []glossaryEntry
}

func glossarySections() []glossarySection {
	return []glossarySection{
		{
			Title: "ОПРЕДЕЛЕНИЯ",
			Entries: []glossaryEntry{
				{"Представленный размер", "Размер карточки, суммарный остаток которого на складах WB строго больше порога шт (по умолчанию >2; переключается в шапке). Источник остатка — stocks_daily_warehouses последнего снапшота, агрегат SUM(quantity) по размеру (chrt_id) по всем складам."},
				{"Недоступный артикул", "Артикул, у которого представленных размеров меньше порога (по умолчанию <4; переключается в шапке). Артикул без карточки WB недоступен тривиально: 0 представленных размеров, поэтому он входит и в герой-KPI, и в меру «Свободно на 1С» — а отдельной секцией/фильтром «Без карточки» его видно изолированно. Короткая трактовка «только с карточкой»: герой минус KPI «Без карточки WB»."},
				{"Лежит на складе 1С", "Свободный остаток (free) артикула на складе из конфигурации (по умолчанию «Внуково») в последнем снапшоте onec_rests. Резерв 1С (reserv) показывается колонкой, но в отбор не входит. Розничные склады, «Товар в пути» и зеркало учёта «Склад ОПТ» в меру НЕ входят: «Склад ОПТ» дублирует Внуково до единицы — суммирование давало бы двойной счёт."},
				{"Добор (вид «Восстановление»)", "Альтернативная рамка чтения того же среза (переключатель «Дефицит / Восстановление»): артикулы группируются по числу размеров, которое нужно поднять выше порога, чтобы карточка стала доступной. «+1 размер» — quick win: поднятие одного размера возвращает свободный остаток артикула в продажу целиком. «В нуле» — ни один размер не представлен (разбирать причину, а не добор), «нет карточки» — товар вообще не выставлен. Пороги, фильтры и данные те же — меняется только рамка: не «сколько пропало», а «что и в каком порядке возвращать»."},
				{"Размеров в карточке", "Количество строк card_sizes у nm_id — полная сетка размеров, заведённая в карточку WB, независимо от остатков."},
			},
		},
		{
			Title: "СРЕЗ И СВЕЖЕСТЬ",
			Entries: []glossaryEntry{
				{"День снапшота", "Дата последнего снапшота stocks_daily_warehouses: остатки WB «на сегодня вечером» (или на последний скачанный день). Остатки 1С — свой последний снапшот onec_rests; справочник 1С — последняя выгрузка onec_goods. Даты в шапке дашборда."},
				{"Universe среза", "Артикулы 1С со свободным остатком (free > 0) на складе конфигурации. Артикулы без остатка 1С в срез не входят: отчёт про «лежит на 1С, но не представлено на WB»."},
				{"Год выпуска", "Символы 2–3 артикула продавца (конвенция репо): 12xxxxxxx → 2012, 25xxxxxxx → 2025. Год 0 = по артикулу не определился (не-цифры или короткий артикул)."},
				{"Категория", "category_level1_name справочника 1С с fallback на category; фильтр L2 — category_level2_name. Иерархия товарных групп 1С (а-ля «Аксессуары»)."},
			},
		},
		{
			Title: "ГРАНИЦЫ ДАННЫХ",
			Entries: []glossaryEntry{
				{"Порог на клиенте", "Переключатели порогов в шапке пересчитывают вердикты в браузере из пер-размерных количеств (таблица sizes). Данные в analytical.* хранят вердикты по порогам конфигурации nightly-прогона — при смене порогов в шапке цифры дашборда и хранимые флаги могут расходиться до следующего прогона."},
				{"Один артикул — одна карточка", "Связка cards.vendor_code = onec_goods.article. Несколько карточек WB на один артикул 1С схлопнутся в одну строку снапшота (на текущих данных дублей нет)."},
				{"Остаток WB ≠ остаток FBS", "stocks_daily_warehouses — остатки на складах WB (FBO). Товар «в пути к клиенту» (in_way_*) в меру представленности не входит."},
				{"Длины артикулов", "Артикулы длиной из exclude_lengths (по умолчанию 6 и 7 символов) в срез не входят — конвенция репо (даунлоадеры/фиксёры/collection-readiness): 6-значные — легаси-нумерация (дают мусорный «год» 2081/2083/2094 по символам 2–3), 7-значные — старая нумерация «совсем старые». Пустой список [] в конфиге отключает фильтр."},
				{"Retention", "История снапшотов в analytical.* хранится 90 суток (конфиг retention_days); дельты KPI считаются относительно предыдущего сохранившегося дня."},
			},
		},
	}
}

// methodologyLines — текст подвала «Методика».
func methodologyLines() []string {
	return []string{
		"Срез собирается утилитой size-availability-report после основной загрузки сырых данных: RAW public.stocks_daily_warehouses / card_sizes / cards / onec_goods / onec_rests → analytical.size_availability_daily (грейн день × артикул) + analytical.size_availability_sizes_daily (день × карточка × размер, включая нулевые). Запись идемпотентна: повторный прогон дня обновляет снапшот (ON CONFLICT DO UPDATE).",
		"Размер «представлен» ⇔ SUM(quantity) по (nm_id, chrt_id) последнего снапшота стоков строго больше порога шт (по умолчанию 2). Артикул «недоступен» ⇔ представленных размеров меньше порога (по умолчанию 4). Оба порога переключаются в шапке дашборда — пересчёт из пер-размерных количеств на клиенте, без обращения к данным.",
		"Остаток 1С — свободный (free) по складу конфигурации («Внуково») из последнего снапшота onec_rests; резерв показывается колонкой, в отбор не входит. «Склад ОПТ» — зеркало Внуково с идентичными количествами, в меру не входит (двойной счёт); розничные склады и «Товар в пути» исключены.",
		"Universe — артикулы с free > 0 на складе конфигурации; артикулы без карточки WB выделены отдельной секцией и вердиктом «Нет карточки». Год выпуска — символы 2–3 артикула продавца (конвенция репо), 0 = не определился.",
		"Дедупликация связок (защита от расщепления строки снапшота): несколько карточек WB на один артикул схлопываются в MIN(nm_id); несколько справочных строк 1С на артикул — свежая по downloaded_at; свободный остаток артикула суммируется по всем его guid. Пересборка снапшота дня атомарна (DELETE+INSERT в одной транзакции): «призраков» от повторных прогонов и рассинхрона daily/sizes не бывает.",
		"Дашборд — статический офлайн-HTML: данные в payload JSON внутри файла, диаграммы echarts 5.5.1 (Apache-2.0) инлайном. Ничего не отправляет и не запрашивает.",
	}
}
